def _persist_social_token(credentials: Credentials, social_token: SocialToken) -> None:
    social_token.token = credentials.token
    if credentials.refresh_token:
        social_token.token_secret = credentials.refresh_token
    social_token.expires_at = (
        credentials.expiry.replace(tzinfo=timezone.utc) if credentials.expiry else None
    )
    social_token.save(update_fields=["token", "token_secret", "expires_at"])


def _persist_ticket_credentials(credentials: Credentials, ticket: Any) -> None:
    ticket.access_token = credentials.token or ""
    if credentials.refresh_token:
        ticket.refresh_token = credentials.refresh_token
    ticket.token_expiry = credentials.expiry
    ticket.save(update_fields=["_access_token", "_refresh_token", "token_expiry"])


def _build_credentials(
    *,
    access_token: str,
    refresh_token: str,
    token_expiry: datetime | None,
    client_id: str,
    client_secret: str,
) -> Credentials:
    credentials = Credentials(
        token=access_token or None,
        refresh_token=refresh_token or None,
        token_uri=TOKEN_URI,
        client_id=client_id,
        client_secret=client_secret,
        scopes=SCOPES,
    )
    credentials.expiry = token_expiry
    return credentials


def _ensure_valid_credentials(
    credentials: Credentials,
    *,
    account_label: str,
    persist_credentials: Callable[[Credentials], None] | None = None,
) -> Credentials:
    if credentials.expired and credentials.refresh_token:
        try:
            logger.info("Refreshing Google API token for %s", account_label)
            credentials.refresh(Request())
        except RefreshError as exc:
            if _is_invalid_grant_error(exc):
                raise GoogleCalendarPermanentError(
                    f"Google authorization for {account_label} is no longer valid."
                ) from exc
            raise GoogleCalendarTransientError(
                f"Failed to refresh Google Calendar credentials for {account_label}."
            ) from exc
        except Exception as exc:
            if _is_invalid_grant_error(exc):
                raise GoogleCalendarPermanentError(
                    f"Google authorization for {account_label} is no longer valid."
                ) from exc
            raise GoogleCalendarTransientError(
                f"Unexpected refresh failure for {account_label}."
            ) from exc

        if persist_credentials is not None:
            persist_credentials(credentials)

    if not credentials.valid:
        raise GoogleCalendarPermanentError(
            f"Google credentials are invalid for {account_label}."
        )

