@login_required
def external_calendar_delete(request: HttpRequest, calendar_id: str) -> HttpResponse:
    """
    Delete an external calendar and all its associated events
    """
    user = cast(User, request.user)  # login_required guarantees User
    logger.info(
        f"external_calendar_delete called: method={request.method}, calendar_id={calendar_id}, user={user.username}"
    )

    calendar = get_object_or_404(ExternalCalendarAccount, id=calendar_id, user=user)

    logger.info(f"Found calendar: {calendar.account_name} (id={calendar.id})")

    if request.method == "POST":
        logger.info("Processing POST request to delete calendar")
        account_name = calendar.account_name

        try:
            # Use a transaction to ensure all related data is deleted properly
            with transaction.atomic():
                # Get all events associated with this calendar
                # Use calendar_id field which stores the ExternalCalendarAccount.id
                events = Event.objects.filter(
                    is_external=True,
                    calendar_id=str(calendar.id),
                    external_source=calendar.provider,
                )

                # Delete all events associated with this calendar
                event_count = events.count()
                logger.info(f"Deleting {event_count} events associated with calendar")
                events.delete()

                # Delete all related records
                DeletedExternalEvent.objects.filter(calendar=calendar).delete()
                ModifiedExternalEvent.objects.filter(calendar=calendar).delete()
                SyncLog.objects.filter(calendar=calendar).delete()

                # Delete the calendar visibility settings
                try:
                    calendar.visibility.delete()
                except CalendarVisibility.DoesNotExist:
                    pass

                # Finally delete the calendar itself
                logger.info(f"Deleting calendar {calendar.id}")
                calendar.delete()
                logger.info("Calendar deleted successfully")

            messages.success(
                request,
                f'Calendar "{account_name}" and {event_count} associated events were deleted successfully.',
            )
            return redirect("calendars:external_calendar_list")
        except Exception as e:
            logger.error(f"Error deleting calendar: {str(e)}", exc_info=True)
            messages.error(
                request,
                f"Error deleting calendar: {str(e)}",
            )
            return redirect(
                "calendars:external_calendar_detail", calendar_id=calendar_id
            )

    context = {
        "calendar": calendar,
    }

    return render(request, "calendars/external_confirm_delete.html", context)


