        SyncLog.objects.filter(calendar=account).delete()  # Assuming 'calendar' FK name
        ModifiedExternalEvent.objects.filter(calendar=account).delete()
        DeletedExternalEvent.objects.filter(calendar=account).delete()
        # Delete future events linked by string calendar_id (not a FK, no CASCADE).
