@shared_task
def process_voice_draft_task(draft_id: UUID | str) -> dict[str, Any]:
    """
    Celery task to process a voice recording draft asynchronously.

    This task:
    1. Retrieves the EventDraft by ID
    2. Validates and downloads the audio file
    3. Transcribes it using OpenAI Whisper
    4. Extracts event data using GPT
    5. Updates the draft with the results

    Args:
        draft_id: UUID of the EventDraft to process

    Returns:
        dict: Processing result with success status and data/error
    """
    from .audio_services import VoiceRecordingProcessorService
    from .models import EventDraft

    try:
        draft = EventDraft.objects.get(id=draft_id)
    except EventDraft.DoesNotExist:
        logger.error(f"EventDraft {draft_id} not found for voice processing")
        return {"success": False, "error": "Draft not found"}

    logger.info(
        f"Starting async voice processing for draft {draft_id} by user {draft.creator.id}"
    )

    result = VoiceRecordingProcessorService.process_voice_draft(draft)

    if result.get("success"):
        logger.info(f"Successfully processed voice draft {draft_id}")
    else:
        logger.error(f"Failed to process voice draft {draft_id}: {result.get('error')}")

    return result


