def sync_event_to_google_task(self, event_id: UUID | str) -> None:
    from calendars.google_calendar_api import (
        create_google_calendar_event_strict,
        delete_google_calendar_event_strict,
        format_event_for_google,
        update_google_calendar_event_strict,
    )

    from .models import Event

    normalized_event_id = _normalize_event_id(event_id)
    if normalized_event_id is None:
        return

    try:
        event = Event.objects.select_related("creator").get(id=normalized_event_id)
    except Event.DoesNotExist:
        logger.warning(
            "Event %s not found for Google Calendar sync", normalized_event_id
        )
        return

    if event.is_external:
        logger.debug("Skipping Google Calendar sync for external event %s", event.id)
        return

    if not event.creator_id:
        logger.warning(
            "Event %s has no creator, cannot sync to Google Calendar.", event.id
        )
        return

    user = event.creator
    if not _user_has_google_sync_enabled(user, event.id):
        return

    event_data = format_event_for_google(event)  # type: ignore[no-untyped-call]
    current_gcal_event_id = event.gcal_event_id or ""

    if current_gcal_event_id:
        try:
            logger.info(
                "Updating event %s (gcal_id: %s) on Google Calendar for user %s",
                event.id,
                current_gcal_event_id,
                user.id,
            )
            update_google_calendar_event_strict(  # type: ignore[no-untyped-call]
                user,
                current_gcal_event_id,
                event_data,
            )
            logger.info("Successfully updated event %s on Google Calendar.", event.id)
            return
        except GoogleCalendarRemoteMissingError:
            cleared = Event.objects.filter(
                pk=event.pk,
                gcal_event_id=current_gcal_event_id,
            ).update(gcal_event_id="")
            if not cleared:
                current_local_gcal_id = (
                    Event.objects.filter(pk=event.pk)
                    .values_list("gcal_event_id", flat=True)
                    .first()
                )
                if current_local_gcal_id is None:
                    logger.warning(
                        "Event %s disappeared before its stale Google sync id could be cleared",
                        event.id,
                    )
                    return
                if current_local_gcal_id != current_gcal_event_id:
                    logger.info(
                        "Skipping recreate for event %s because another worker already updated the Google id",
                        event.id,
                    )
                    return

    try:
        logger.info(
            "Creating event %s on Google Calendar for user %s", event.id, user.id
        )
        created_gcal_event = create_google_calendar_event_strict(  # type: ignore[no-untyped-call]
            user, event_data
        )
        gcal_id = created_gcal_event.get("id") if created_gcal_event else None
        if not gcal_id:
            raise GoogleCalendarPermanentError(
                f"Google create for event {event.id} returned no remote id."
            )

        claimed = (
            Event.objects.filter(pk=event.pk)
            .filter(Q(gcal_event_id__isnull=True) | Q(gcal_event_id=""))
            .update(gcal_event_id=gcal_id)
        )
        if claimed:
            logger.info(
                "Successfully created event %s on Google Calendar with ID: %s",
                event.id,
                gcal_id,
            )
            return

        current_local_gcal_id = (
            Event.objects.filter(pk=event.pk)
            .values_list("gcal_event_id", flat=True)
            .first()
        )
        if current_local_gcal_id is None or current_local_gcal_id != gcal_id:
            logger.warning(
                "Created Google Calendar event %s for local event %s, but the local row could not claim it. Cleaning up the remote event.",
                gcal_id,
                event.id,
            )
            delete_google_calendar_event_strict(user, gcal_id)  # type: ignore[no-untyped-call]
    except GoogleCalendarAccountUnlinkedError as exc:
        # User disconnected Google or never linked it — expected, not actionable.
        logger.info(
            "Skipping Google Calendar sync for event %s: %s", event.id, exc
        )
    except GoogleCalendarPermanentError as exc:
        logger.error(
            "Permanent Google Calendar sync failure for event %s and user %s: %s",
            event.id,
            user.id,
            exc,
        )


