logger = logging.getLogger(__name__)

MIN_SOURCE_CONFIDENCE = 0.85
MIN_ACCEPT_SCORE = 0.85
MIN_SCORE_GAP = 0.10
LOCAL_MIN_ACCEPT_SCORE = 0.90
LOCAL_MIN_SCORE_GAP = 0.05
SEARCH_URL = "https://places.googleapis.com/v1/places:searchText"
SEARCH_FIELD_MASK = (
    "places.id,places.displayName,places.formattedAddress,"
    "places.location,places.googleMapsUri"
)
DETAILS_URL_TEMPLATE = "https://places.googleapis.com/v1/places/{place_id}"
DETAILS_FIELD_MASK = (
    "websiteUri,nationalPhoneNumber,rating,userRatingCount,businessStatus,"
    "regularOpeningHours.weekdayDescriptions,googleMapsLinks.reviewsUri,"
    "googleMapsLinks.photosUri"
)
REQUEST_TIMEOUT = 10
STRONG_ADDRESS_MATCH_SCORE = 0.96

_STREET_TOKEN_ALIASES = {
    "street": "st",
    "st": "st",
    "road": "rd",
    "rd": "rd",
    "avenue": "ave",
    "ave": "ave",
    "trail": "trl",
    "trl": "trl",
    "highway": "hwy",
    "hwy": "hwy",
    "lane": "ln",
    "ln": "ln",
    "drive": "dr",
    "dr": "dr",
    "boulevard": "blvd",
    "blvd": "blvd",
    "court": "ct",
    "ct": "ct",
    "place": "pl",
    "pl": "pl",
    "terrace": "ter",
    "ter": "ter",
    "parkway": "pkwy",
    "pkwy": "pkwy",
}
_ADDRESS_IGNORE_TOKENS = {"usa", "us", "united", "states"}


@dataclass(slots=True)
class AddressParts:
    house_number: str
    street_tokens: tuple[str, ...]
    locality_tokens: tuple[str, ...]


@dataclass(slots=True)
class PlaceMatchCandidate:
    place_id: str
