def _normalize_text(value: str) -> str:
    normalized = re.sub(r"[^a-z0-9 ]+", " ", value.lower())
    return re.sub(r"\s+", " ", normalized).strip()


def _similarity(a: str, b: str) -> float:
    if not a or not b:
        return 0.0
    return SequenceMatcher(None, _normalize_text(a), _normalize_text(b)).ratio()


def _tokenize_address_segment(value: str) -> list[str]:
    normalized_routes = re.sub(
        r"\bnorth\s+carolina\s+(?:highway|hwy)\s*(\d+)\b",
        r"nc\1",
        value.lower(),
    )
    compacted = re.sub(
        r"\b([a-z]+)\s*-\s*(\d+)\b",
        r"\1\2",
        normalized_routes,
    )
    raw_tokens = re.findall(r"[a-z0-9]+", compacted)
    tokens: list[str] = []
    for raw_token in raw_tokens:
        if raw_token in _ADDRESS_IGNORE_TOKENS:
            continue
        # Preserve a leading 5-digit token as a possible street number.
        if re.fullmatch(r"\d{5}(?:\d{4})?", raw_token) and tokens:
            continue
        tokens.append(_STREET_TOKEN_ALIASES.get(raw_token, raw_token))
    return tokens


def _parse_address_parts(value: str) -> AddressParts | None:
    segments = [
        _tokenize_address_segment(segment)
        for segment in value.split(",")
        if segment.strip()
    ]
    segments = [segment for segment in segments if segment]
    if not segments:
        return None

    street_index = next(
        (
            index
            for index, segment in enumerate(segments)
            if any(token.isdigit() for token in segment)
        ),
        None,
    )
    if street_index is None:
        return None

    street_segment = segments[street_index]
    house_index = next(
        (index for index, token in enumerate(street_segment) if token.isdigit()),
        None,
    )
    if house_index is None:
        return None

    house_number = street_segment[house_index]
    street_tokens = tuple(street_segment[house_index + 1 :])
    locality_tokens = tuple(
        token
        for segment in segments[street_index + 1 :]
        for token in segment
        if not token.isdigit() and len(token) > 2
    )
    return AddressParts(
        house_number=house_number,
        street_tokens=street_tokens,
        locality_tokens=locality_tokens,
    )


def _is_strong_address_match(query: str, candidate: str) -> bool:
    query_parts = _parse_address_parts(query)
    candidate_parts = _parse_address_parts(candidate)
    if query_parts is None or candidate_parts is None:
        return False
    if query_parts.house_number != candidate_parts.house_number:
        return False

    query_street_tokens = set(query_parts.street_tokens)
    candidate_street_tokens = set(candidate_parts.street_tokens)
    if not query_street_tokens:
        return False
    if not query_street_tokens.issubset(candidate_street_tokens):
        return False

    query_locality_tokens = set(query_parts.locality_tokens)
    candidate_locality_tokens = set(candidate_parts.locality_tokens)
    if query_locality_tokens and not (
        query_locality_tokens & candidate_locality_tokens
    ):
        return False

    return True


def _lookup_base_text(event: RegionEvent) -> str:
    variants = build_lookup_texts(event)
    if not variants:
        return ""
    return variants[0]


def _looks_like_address(value: str) -> bool:
    normalized = _normalize_text(value)
    if not normalized:
        return False
    if re.match(r"^\d+\s", normalized):
        return True
    street_tokens = {
        "street",
        "st",
        "road",
        "rd",
        "avenue",
        "ave",
        "trail",
        "trl",
        "highway",
        "hwy",
        "lane",
        "ln",
        "drive",
        "dr",
        "boulevard",
        "blvd",
        "court",
        "ct",
        "way",
    }
    return any(token in normalized.split() for token in street_tokens)


def _match_texts(event: RegionEvent) -> tuple[str, str]:
    location_text = (event.location or "").strip()
    address_text = (event.address or "").strip()

    if address_text and _looks_like_address(address_text):
        return location_text, address_text
    if _looks_like_address(location_text):
        return "", location_text
    return location_text, ""


def _locality_text(event: RegionEvent) -> str:
    address_text = (event.address or "").strip()
    if address_text and not _looks_like_address(address_text):
        return address_text
    return ""


def build_lookup_texts(event: RegionEvent) -> list[str]:
    venue_text = (event.location or "").strip()
    street_text = ""
    locality_text = _locality_text(event)
    address_text = (event.address or "").strip()
    if address_text and _looks_like_address(address_text):
        street_text = address_text
    elif not address_text and _looks_like_address(venue_text):
        street_text = venue_text
        venue_text = ""

    region_name = event.region_calendar.region.name.strip()
    variants: list[str] = []
    seen: set[str] = set()

    def add_variant(*parts: str) -> None:
        cleaned = [part.strip() for part in parts if part and part.strip()]
        if not cleaned:
            return
        text = ", ".join(cleaned)
        normalized = _normalize_text(text)
        if not normalized or normalized in seen:
            return
        seen.add(normalized)
        variants.append(text)

    if venue_text and street_text:
        add_variant(venue_text, street_text)
    if venue_text and locality_text:
        add_variant(venue_text, locality_text)
    if venue_text and region_name:
        add_variant(venue_text, region_name)
    if venue_text:
        add_variant(venue_text)
    if street_text and region_name:
        add_variant(street_text, region_name)
    if street_text:
        add_variant(street_text)
    if locality_text and region_name:
        add_variant(locality_text, region_name)
    if locality_text:
        add_variant(locality_text)
    return variants


def build_lookup_text(event: RegionEvent) -> str:
    return _lookup_base_text(event)


def has_lookup_text(event: RegionEvent) -> bool:
    return bool(build_lookup_texts(event))


def should_skip_for_low_confidence(event: RegionEvent) -> bool:
    return (
        event.source_confidence is not None
        and event.source_confidence < MIN_SOURCE_CONFIDENCE
    )


def queue_region_event_place_enrichment(
    event: RegionEvent,
    *,
    force: bool = False,
) -> bool:
    """Queue async enrichment for an imported event when it has usable lookup data."""
    update_fields: list[str] = []

    if not has_lookup_text(event):
        if event.location_enrichment_status != "NO_LOOKUP_TEXT":
            event.location_enrichment_status = "NO_LOOKUP_TEXT"
            event.matched_business = None
            event.location_match_source = ""
            update_fields.extend(
                [
                    "location_enrichment_status",
                    "matched_business",
                    "location_match_source",
                ]
            )
        if update_fields:
            event.save(update_fields=update_fields)
        return False

    if should_skip_for_low_confidence(event):
        if event.location_enrichment_status != "SKIPPED_LOW_CONFIDENCE":
            event.location_enrichment_status = "SKIPPED_LOW_CONFIDENCE"
            event.google_match_score = None
            event.google_place_id = ""
            event.google_maps_uri = ""
            event.matched_business = None
            event.location_match_source = ""
            update_fields.extend(
                [
                    "location_enrichment_status",
                    "google_match_score",
                    "google_place_id",
                    "google_maps_uri",
                    "matched_business",
                    "location_match_source",
                ]
            )
        if update_fields:
            event.save(update_fields=update_fields)
        return False

    if (
        not force
        and event.google_place_id
        and event.location_enrichment_status == "MATCHED"
    ):
        return False

    event.location_enrichment_status = "QUEUED"
    event.google_match_score = None
    update_fields.extend(["location_enrichment_status", "google_match_score"])
    event.save(update_fields=update_fields)

    from trips.tasks import enrich_region_event_place_task

    event_id = event.id
    assert event_id is not None

    def enqueue_task() -> None:
        enrich_region_event_place_task.delay(event_id)

    transaction.on_commit(enqueue_task)
    return True


class RegionEventPlaceEnrichmentService:
    """Resolve Google Places data for a RegionEvent."""

    def enrich_event(self, region_event_id: int) -> RegionEvent | None:
        try:
            event = RegionEvent.objects.select_related("region_calendar__region").get(
                id=region_event_id
            )
        except RegionEvent.DoesNotExist:
            logger.warning(
                "RegionEvent %s not found for place enrichment",
                region_event_id,
            )
            return None

        if should_skip_for_low_confidence(event):
            self._mark_status(event, "SKIPPED_LOW_CONFIDENCE")
            return event

        lookup_texts = build_lookup_texts(event)
        if not lookup_texts:
            self._mark_status(event, "NO_LOOKUP_TEXT")
            return event

        local_business = self._match_local_business(event)
        if local_business is not None:
            self._apply_business_match(
                event,
                local_business,
                match_source="LOCAL_BUSINESS",
            )
            return event

        api_key = getattr(settings, "GOOGLE_PLACES_API_KEY", "")
        if not api_key:
            logger.warning("GOOGLE_PLACES_API_KEY not configured")
            self._mark_status(event, "ERROR")
            return event

        try:
            raw_places_by_key: dict[str, dict[str, Any]] = {}
            for lookup_text in lookup_texts:
                payload = {
                    "textQuery": lookup_text,
                    "maxResultCount": 5,
                }
                response = requests.post(
                    SEARCH_URL,
                    json=payload,
                    headers={
                        "Content-Type": "application/json",
                        "X-Goog-Api-Key": api_key,
                        "X-Goog-FieldMask": SEARCH_FIELD_MASK,
                    },
                    timeout=REQUEST_TIMEOUT,
                )
                response.raise_for_status()
                response_data = response.json()
                for raw_place in response_data.get("places") or []:
                    place_key = str(raw_place.get("id") or "").strip()
                    if not place_key:
                        display_name = str(
                            raw_place.get("displayName", {}).get("text") or ""
                        ).strip()
                        formatted_address = str(
                            raw_place.get("formattedAddress") or ""
                        ).strip()
                        place_key = _normalize_text(
                            f"{display_name}|{formatted_address}"
                        )
                    existing = raw_places_by_key.get(place_key)
                    if existing is None:
                        raw_places_by_key[place_key] = raw_place
                        continue
                    merged = dict(existing)
                    for key, value in raw_place.items():
                        if not merged.get(key) and value:
                            merged[key] = value
                    raw_places_by_key[place_key] = merged
        except requests.RequestException:
            logger.exception(
                "Google Places request failed for RegionEvent %s",
                region_event_id,
            )
            self._mark_status(event, "ERROR")
            return event
        except ValueError:
            logger.exception(
                "Google Places response parsing failed for RegionEvent %s",
                region_event_id,
            )
            self._mark_status(event, "ERROR")
            return event

        candidates = self._build_candidates(
            event,
            lookup_texts=lookup_texts,
            raw_places=list(raw_places_by_key.values()),
        )
        if not candidates:
            self._mark_status(event, "NO_MATCH")
            return event

        best = candidates[0]
        second = candidates[1] if len(candidates) > 1 else None

        if best.score < MIN_ACCEPT_SCORE:
            self._mark_status(event, "NO_MATCH")
            return event

        if second is not None and (best.score - second.score) < MIN_SCORE_GAP:
            self._mark_status(event, "AMBIGUOUS")
            return event

        details = self._fetch_place_details(best.place_id, api_key)
        business = self._upsert_business_listing_from_google(event, best, details)
        self._apply_business_match(
            event,
            business,
            match_source="GOOGLE_FALLBACK",
            google_match_score=best.score,
        )
        return event

    def _fetch_place_details(self, place_id: str, api_key: str) -> PlaceDetails | None:
        if not place_id:
            return None

        try:
            response = requests.get(
                DETAILS_URL_TEMPLATE.format(place_id=place_id),
                headers={
                    "Content-Type": "application/json",
                    "X-Goog-Api-Key": api_key,
                    "X-Goog-FieldMask": DETAILS_FIELD_MASK,
                },
                timeout=REQUEST_TIMEOUT,
            )
            response.raise_for_status()
            payload = response.json()
        except requests.RequestException:
            logger.exception(
                "Google Place Details request failed for place %s", place_id
            )
            return None
        except ValueError:
            logger.exception(
                "Google Place Details parsing failed for place %s", place_id
            )
            return None

        google_maps_links = payload.get("googleMapsLinks") or {}
        raw_opening_hours = payload.get("regularOpeningHours") or {}
        weekday_descriptions = raw_opening_hours.get("weekdayDescriptions") or []
        normalized_hours = [str(line).strip() for line in weekday_descriptions if line]
        raw_rating_count = payload.get("userRatingCount")
        rating_count = (
            int(raw_rating_count)
            if isinstance(raw_rating_count, int | float)
            and raw_rating_count is not None
            else None
        )
        raw_rating = payload.get("rating")
        rating = (
            float(raw_rating)
            if isinstance(raw_rating, int | float) and raw_rating is not None
            else None
        )

        return PlaceDetails(
            website_uri=str(payload.get("websiteUri") or ""),
            phone_number=str(payload.get("nationalPhoneNumber") or ""),
            reviews_uri=str(google_maps_links.get("reviewsUri") or ""),
            photos_uri=str(google_maps_links.get("photosUri") or ""),
            rating=rating,
            user_rating_count=rating_count,
            business_status=str(payload.get("businessStatus") or ""),
            opening_hours=normalized_hours,
        )

    def _match_local_business(self, event: RegionEvent) -> BusinessListing | None:
        venue_text, address_text = _match_texts(event)
        candidates = (
            BusinessListing.objects.filter(
                region=event.region_calendar.region,
                is_active=True,
            )
            .prefetch_related("aliases")
            .order_by("display_name")
        )
        scored: list[LocalBusinessMatchCandidate] = []

        for business in candidates:
            score = self._score_local_business_candidate(
                business,
                venue_text=venue_text,
                address_text=address_text,
            )
            if score > 0:
                scored.append(
                    LocalBusinessMatchCandidate(business=business, score=score)
                )

        if not scored:
            return None

        scored.sort(key=lambda item: item.score, reverse=True)
        best = scored[0]
        second = scored[1] if len(scored) > 1 else None

        if best.score < LOCAL_MIN_ACCEPT_SCORE:
            return None
        if second is not None and (best.score - second.score) < LOCAL_MIN_SCORE_GAP:
            return None
        return best.business

    def _score_local_business_candidate(
        self,
        business: BusinessListing,
        *,
        venue_text: str,
        address_text: str,
    ) -> float:
        alias_values = [alias.alias for alias in business.aliases.all()]
        name_choices = [business.display_name, *alias_values]
        name_score = (
            max(
                (_similarity(venue_text, choice) for choice in name_choices),
                default=0.0,
            )
            if venue_text
            else 0.0
        )
        address_score = (
            _similarity(address_text, business.canonical_address)
            if address_text
            else 0.0
        )
        strong_address_match = (
            _is_strong_address_match(address_text, business.canonical_address)
            if address_text
            else False
        )

        if address_text and venue_text:
            return max(
                (name_score * 0.65) + (address_score * 0.35),
                STRONG_ADDRESS_MATCH_SCORE
                if strong_address_match and name_score >= 0.5
                else 0.0,
                address_score if address_score >= 0.97 else 0.0,
            )
        if address_text:
            return max(
                address_score,
                STRONG_ADDRESS_MATCH_SCORE if strong_address_match else 0.0,
            )
        return name_score

    def _build_candidates(
        self,
        event: RegionEvent,
        *,
        lookup_texts: list[str],
        raw_places: list[dict[str, Any]],
    ) -> list[PlaceMatchCandidate]:
        venue_text, address_text = _match_texts(event)
        locality_text = _locality_text(event)
        base_text = (
            venue_text or locality_text or address_text or _lookup_base_text(event)
        )
        region_tokens = self._address_bonus_tokens(event, lookup_texts)
        candidates: list[PlaceMatchCandidate] = []

        for raw_place in raw_places:
            display_name = str(
                raw_place.get("displayName", {}).get("text") or ""
            ).strip()
            formatted_address = str(raw_place.get("formattedAddress") or "").strip()
            if not display_name:
                continue

            name_score = _similarity(venue_text, display_name) if venue_text else 0.0
            address_score = (
                _similarity(address_text, formatted_address) if address_text else 0.0
            )
            locality_score = (
                _similarity(locality_text, formatted_address) if locality_text else 0.0
            )
            strong_address_match = (
                _is_strong_address_match(address_text, formatted_address)
                if address_text
                else False
            )
            fallback_score = 0.0
            if venue_text:
                fallback_score = name_score
                if locality_text:
                    fallback_score = min(
                        1.0,
                        max(
                            fallback_score,
                            (name_score * 0.85) + (locality_score * 0.15),
                        ),
                    )
            elif locality_text:
                fallback_score = locality_score
            elif base_text:
                fallback_score = _similarity(base_text, display_name)

            if venue_text and address_text:
                score = max(
                    (name_score * 0.65) + (address_score * 0.35),
                    STRONG_ADDRESS_MATCH_SCORE if strong_address_match else 0.0,
                    address_score if address_score >= 0.95 else 0.0,
                )
            elif address_text:
                score = max(
                    address_score,
                    STRONG_ADDRESS_MATCH_SCORE if strong_address_match else 0.0,
                )
            else:
                score = fallback_score

            if region_tokens:
                candidate_address_normalized = _normalize_text(formatted_address)
                matched_count = sum(
                    1
                    for token in region_tokens
                    if token in candidate_address_normalized
                )
                score = min(1.0, score + min(0.05, matched_count * 0.02))

            location = raw_place.get("location") or {}
            latitude = location.get("latitude")
            longitude = location.get("longitude")
            candidates.append(
                PlaceMatchCandidate(
                    place_id=str(raw_place.get("id") or ""),
                    display_name=display_name,
                    formatted_address=formatted_address,
                    latitude=float(latitude) if latitude is not None else None,
                    longitude=float(longitude) if longitude is not None else None,
                    google_maps_uri=str(raw_place.get("googleMapsUri") or ""),
                    score=score,
                )
            )

        return sorted(candidates, key=lambda item: item.score, reverse=True)

    def _address_bonus_tokens(
        self,
        event: RegionEvent,
        lookup_texts: list[str],
    ) -> set[str]:
        tokens = {
            token
            for token in _normalize_text(event.region_calendar.region.name).split()
            if len(token) > 2
        }
        for lookup_text in lookup_texts:
            for part in lookup_text.split(",")[1:]:
                for token in _normalize_text(part).split():
                    if len(token) > 1:
                        tokens.add(token)
        return tokens

    def _upsert_business_listing_from_google(
        self,
        event: RegionEvent,
        match: PlaceMatchCandidate,
        details: PlaceDetails | None,
    ) -> BusinessListing:
        preferred_canonical_address = (
            str(event.address or "").strip()
            if str(event.address or "").strip()
            and _looks_like_address(str(event.address))
            else (
                match.formatted_address
                or event.address
                or event.location
                or match.display_name
            )
        )
        business = BusinessListing.objects.filter(
            region=event.region_calendar.region,
            google_place_id=match.place_id,
        ).first()
        created = business is None

        if business is None:
            business = BusinessListing(
                region=event.region_calendar.region,
                display_name=match.display_name or (event.location or event.name)[:255],
                canonical_address=preferred_canonical_address[:500],
                latitude=match.latitude,
                longitude=match.longitude,
                google_place_id=match.place_id,
                google_maps_uri=match.google_maps_uri,
                import_source="GOOGLE",
                is_verified=False,
            )

        business.google_place_id = match.place_id
        business.google_maps_uri = match.google_maps_uri

        if created or (business.import_source == "GOOGLE" and not business.is_verified):
            business.display_name = match.display_name or business.display_name
            business.canonical_address = preferred_canonical_address[:500]
            if match.latitude is not None:
                business.latitude = match.latitude
            if match.longitude is not None:
                business.longitude = match.longitude

        if details is not None:
            business.google_website_uri = details.website_uri
            business.google_phone_number = details.phone_number
            business.google_reviews_uri = details.reviews_uri
            business.google_photos_uri = details.photos_uri
            business.google_rating = details.rating
            business.google_user_rating_count = details.user_rating_count
            business.google_business_status = details.business_status
            business.google_opening_hours = details.opening_hours or []

        business.save()
        self._ensure_business_aliases(business, event)
        return business

    def _ensure_business_aliases(
        self, business: BusinessListing, event: RegionEvent
    ) -> None:
        raw_location = str(event.location or "").strip()
        if not raw_location:
            return
        if _normalize_text(raw_location) == _normalize_text(business.display_name):
            return

        BusinessListingAlias.objects.get_or_create(
            business=business,
            normalized_alias=_normalize_text(raw_location),
            defaults={"alias": raw_location},
        )

