class BusinessListingGoogleEnrichmentService:
    """Refresh Google Places metadata for a BusinessListing."""

    def __init__(self) -> None:
        self._event_service = RegionEventPlaceEnrichmentService()

    def refresh_listing(
        self, listing: BusinessListing
    ) -> BusinessListingGoogleEnrichmentResult:
        api_key = getattr(settings, "GOOGLE_PLACES_API_KEY", "")
        if not api_key:
            logger.warning("GOOGLE_PLACES_API_KEY not configured")
            return BusinessListingGoogleEnrichmentResult(
                status="failed",
                listing=listing,
                reason="missing_api_key",
            )

        try:
            if listing.google_place_id:
                payload = self._fetch_place_payload(listing.google_place_id, api_key)
                if payload is None:
                    return BusinessListingGoogleEnrichmentResult(
                        status="failed",
                        listing=listing,
                        reason="place_details_failed",
                    )
                candidate = self._candidate_from_payload(payload)
                if candidate is None:
                    return BusinessListingGoogleEnrichmentResult(
                        status="failed",
                        listing=listing,
                        reason="invalid_place_payload",
                    )
                payload_details = self._details_from_payload(payload)
                self._apply_google_data(listing, candidate, payload_details)
                return BusinessListingGoogleEnrichmentResult(
                    status="refreshed",
                    listing=listing,
                )

            match, ambiguous_candidates = self._search_best_match(listing, api_key)
            if match is None:
                return BusinessListingGoogleEnrichmentResult(
                    status="ambiguous" if ambiguous_candidates else "skipped",
                    listing=listing,
                    reason="multiple_candidates"
                    if ambiguous_candidates
                    else "no_match",
                    candidates=tuple(ambiguous_candidates),
                )

            place_details = self._fetch_place_details(match.place_id, api_key)
            self._apply_google_data(listing, match, place_details)
            return BusinessListingGoogleEnrichmentResult(
                status="refreshed",
                listing=listing,
            )
        except requests.RequestException:
            logger.exception(
                "Google Places request failed while enriching BusinessListing %s",
                listing.id,
            )
            return BusinessListingGoogleEnrichmentResult(
                status="failed",
                listing=listing,
                reason="request_failed",
            )
        except ValueError:
            logger.exception(
                "Google Places response parsing failed while enriching BusinessListing %s",
                listing.id,
            )
            return BusinessListingGoogleEnrichmentResult(
                status="failed",
                listing=listing,
                reason="parse_failed",
            )

