                )
            details = self._details_from_payload(payload)
            self._apply_google_data(listing, candidate, details)
            return BusinessListingGoogleEnrichmentResult(
                status="refreshed",
                listing=listing,
            )
        except requests.RequestException:
            logger.exception(
                "Google Places request failed while applying choice for BusinessListing %s",
                listing.id,
            )
            return BusinessListingGoogleEnrichmentResult(
                status="failed",
                listing=listing,
                reason="request_failed",
            )
        except ValueError:
            logger.exception(
                "Google Places response parsing failed while applying choice for BusinessListing %s",
                listing.id,
            )
            return BusinessListingGoogleEnrichmentResult(
                status="failed",
                listing=listing,
                reason="parse_failed",
            )

    def backfill_listing_events(self, listing: BusinessListing) -> None:
        """Sync a listing's current place data onto matching region events."""
        self._sync_related_events(listing)

    def _search_best_match(
        self,
        listing: BusinessListing,
        api_key: str,
    ) -> tuple[PlaceMatchCandidate | None, list[PlaceMatchCandidate]]:
        candidates = self._search_candidates(listing, api_key)
        if not candidates:
            return None, []

        best = candidates[0]
        second = candidates[1] if len(candidates) > 1 else None
        if best.score < MIN_ACCEPT_SCORE:
            return None, []
        if second is not None and (best.score - second.score) < MIN_SCORE_GAP:
            resolved = self._break_score_tie(listing, candidates)
            if resolved is not None:
                return resolved, []
            return None, self._ambiguous_contenders(candidates)
        return best, []

    def _search_candidates(
        self,
        listing: BusinessListing,
        api_key: str,
    ) -> list[PlaceMatchCandidate]:
        lookup_context = self._lookup_context(listing)
        lookup_texts = build_lookup_texts(cast(Any, lookup_context))
        if not lookup_texts:
            return []

        raw_places_by_key: dict[str, dict[str, Any]] = {}
        for lookup_text in lookup_texts:
            response = requests.post(
                SEARCH_URL,
                json={
                    "textQuery": lookup_text,
                    "maxResultCount": 5,
                },
                headers={
                    "Content-Type": "application/json",
                    "X-Goog-Api-Key": api_key,
                    "X-Goog-FieldMask": SEARCH_FIELD_MASK,
                },
                timeout=REQUEST_TIMEOUT,
            )
            response.raise_for_status()
            payload = response.json()
            for raw_place in payload.get("places") or []:
                place_key = str(raw_place.get("id") or "").strip()
                if not place_key:
                    display_name = str(
                        raw_place.get("displayName", {}).get("text") or ""
                    ).strip()
                    formatted_address = str(
                        raw_place.get("formattedAddress") or ""
                    ).strip()
                    place_key = _normalize_text(f"{display_name}|{formatted_address}")
                existing = raw_places_by_key.get(place_key)
                if existing is None:
                    raw_places_by_key[place_key] = raw_place
                    continue
                merged = dict(existing)
                for key, value in raw_place.items():
                    if not merged.get(key) and value:
                        merged[key] = value
                raw_places_by_key[place_key] = merged

        candidates = self._event_service._build_candidates(
            cast(Any, lookup_context),
            lookup_texts=lookup_texts,
            raw_places=list(raw_places_by_key.values()),
        )
        return candidates

    def _break_score_tie(
        self,
        listing: BusinessListing,
        candidates: list[PlaceMatchCandidate],
    ) -> PlaceMatchCandidate | None:
        listing_name = str(listing.display_name or "").strip()
        if not listing_name or _looks_like_address(listing_name):
            return None

        best_score = candidates[0].score
        contenders = [
            candidate
            for candidate in candidates
            if (best_score - candidate.score) < MIN_SCORE_GAP
        ]
        if len(contenders) < 2:
            return contenders[0] if contenders else None

        ranked = sorted(
            (
                (
                    candidate,
                    _similarity(listing_name, candidate.display_name),
                    not _looks_like_address(candidate.display_name),
                )
                for candidate in contenders
            ),
            key=lambda item: (item[1], item[2]),
            reverse=True,
        )
        best_candidate, best_name_score, best_is_name_like = ranked[0]
        _, second_name_score, _ = ranked[1]
        if not best_is_name_like:
            return None
        if best_name_score < 0.75:
            return None
        if (best_name_score - second_name_score) < 0.15:
            return None
        return best_candidate

    def _ambiguous_contenders(
        self,
        candidates: list[PlaceMatchCandidate],
    ) -> list[PlaceMatchCandidate]:
        if len(candidates) < 2:
            return []
        best_score = candidates[0].score
        second_score = candidates[1].score
        if best_score < MIN_ACCEPT_SCORE:
            return []
        if (best_score - second_score) >= MIN_SCORE_GAP:
            return []
        return [
            candidate
            for candidate in candidates
            if (best_score - candidate.score) < MIN_SCORE_GAP
        ]

    def _fetch_place_payload(
        self,
        place_id: str,
        api_key: str,
    ) -> dict[str, Any] | None:
        response = requests.get(
            DETAILS_URL_TEMPLATE.format(place_id=place_id),
            headers={
                "Content-Type": "application/json",
                "X-Goog-Api-Key": api_key,
                "X-Goog-FieldMask": DETAILS_FIELD_MASK,
            },
            timeout=REQUEST_TIMEOUT,
        )
        response.raise_for_status()
        return response.json()

    def _fetch_place_details(
        self,
        place_id: str,
        api_key: str,
    ) -> PlaceDetails | None:
        payload = self._fetch_place_payload(place_id, api_key)
        if payload is None:
            return None
        return self._details_from_payload(payload)

    def _candidate_from_payload(
        self,
        payload: dict[str, Any],
    ) -> PlaceMatchCandidate | None:
        display_name = str(payload.get("displayName", {}).get("text") or "").strip()
        place_id = str(payload.get("id") or "").strip()
        if not display_name or not place_id:
            return None

        formatted_address = str(payload.get("formattedAddress") or "").strip()
        location = payload.get("location") or {}
        latitude = location.get("latitude")
        longitude = location.get("longitude")
        return PlaceMatchCandidate(
            place_id=place_id,
            display_name=display_name,
            formatted_address=formatted_address,
            latitude=float(latitude) if latitude is not None else None,
            longitude=float(longitude) if longitude is not None else None,
            google_maps_uri=str(payload.get("googleMapsUri") or "").strip(),
            score=1.0,
        )

    def _details_from_payload(self, payload: dict[str, Any]) -> PlaceDetails:
        google_maps_links = payload.get("googleMapsLinks") or {}
        raw_opening_hours = payload.get("regularOpeningHours") or {}
        weekday_descriptions = raw_opening_hours.get("weekdayDescriptions") or []
        normalized_hours = [str(line).strip() for line in weekday_descriptions if line]
        raw_rating_count = payload.get("userRatingCount")
        rating_count = (
            int(raw_rating_count)
            if isinstance(raw_rating_count, int | float)
            and raw_rating_count is not None
            else None
        )
        raw_rating = payload.get("rating")
        rating = (
            float(raw_rating)
            if isinstance(raw_rating, int | float) and raw_rating is not None
            else None
        )

        return PlaceDetails(
            website_uri=str(payload.get("websiteUri") or ""),
            phone_number=str(payload.get("nationalPhoneNumber") or ""),
            reviews_uri=str(google_maps_links.get("reviewsUri") or ""),
            photos_uri=str(google_maps_links.get("photosUri") or ""),
            rating=rating,
            user_rating_count=rating_count,
            business_status=str(payload.get("businessStatus") or ""),
            opening_hours=normalized_hours,
        )

    def _apply_google_data(
        self,
        listing: BusinessListing,
        candidate: PlaceMatchCandidate,
        details: PlaceDetails | None,
    ) -> None:
        update_fields = [
            "google_place_id",
            "google_maps_uri",
            "google_website_uri",
            "google_phone_number",
            "google_reviews_uri",
            "google_photos_uri",
            "google_rating",
            "google_user_rating_count",
            "google_business_status",
            "google_opening_hours",
        ]
        listing.google_place_id = candidate.place_id
        listing.google_maps_uri = candidate.google_maps_uri

        if listing.latitude is None and candidate.latitude is not None:
            listing.latitude = candidate.latitude
            update_fields.append("latitude")
        if listing.longitude is None and candidate.longitude is not None:
            listing.longitude = candidate.longitude
            update_fields.append("longitude")

        if details is not None:
            listing.google_website_uri = details.website_uri
            listing.google_phone_number = details.phone_number
            listing.google_reviews_uri = details.reviews_uri
            listing.google_photos_uri = details.photos_uri
            listing.google_rating = details.rating
            listing.google_user_rating_count = details.user_rating_count
            listing.google_business_status = details.business_status
            listing.google_opening_hours = details.opening_hours or []

        listing.save(update_fields=update_fields)
        self._ensure_google_display_name_alias(listing, candidate.display_name)
        self._sync_related_events(listing)

    def _sync_related_events(self, listing: BusinessListing) -> None:
        for event in listing.matched_events.all():
            self._event_service._apply_business_match(
                event,
                listing,
                match_source="LOCAL_BUSINESS",
            )
        self._backfill_matching_region_events(listing)

    def _backfill_matching_region_events(self, listing: BusinessListing) -> None:
        candidate_events = (
            RegionEvent.objects.filter(
                region_calendar__region=listing.region,
                matched_business__isnull=True,
            )
            .select_related("region_calendar__region")
            .order_by("id")
        )

        for event in candidate_events.iterator():
            matched_business = self._event_service._match_local_business(event)
            if matched_business is None or matched_business.pk != listing.pk:
                continue
            self._event_service._apply_business_match(
                event,
                listing,
                match_source="LOCAL_BUSINESS",
            )

    def _lookup_context(self, listing: BusinessListing) -> _ListingLookupContext:
        return _ListingLookupContext(
            location=listing.display_name,
            address=listing.canonical_address,
            region_calendar=SimpleNamespace(region=listing.region),
        )

    def _ensure_google_display_name_alias(
        self,
        listing: BusinessListing,
        display_name: str,
    ) -> None:
        alias = str(display_name or "").strip()
        if not alias or _looks_like_address(alias):
            return
        if normalize_business_lookup(alias) == normalize_business_lookup(
            listing.display_name
        ):
            return
        BusinessListingAlias.objects.get_or_create(
            business=listing,
            normalized_alias=normalize_business_lookup(alias),
            defaults={"alias": alias},
        )
